<script setup>
import {computed} from 'vue';
import KnowledgePointBinding from './KnowledgePointBinding.vue';
import {cardKinds,dimensionFields} from '../knowledgeBaseAccess.js';
import HelpHint from './HelpHint.vue';
const props=defineProps({modelValue:{type:Object,required:true},disabled:Boolean,allowGlobal:Boolean,allowExpression:Boolean});
const draft=computed(()=>props.modelValue),kinds=computed(()=>Object.fromEntries(Object.entries(cardKinds).filter(([key])=>props.allowGlobal||key!=='authoring_guideline')));
function addFact(){draft.value.content.facts.push({id:'f-'+crypto.randomUUID(),text:'',applies_when:'',source:''});}
function setExpression(on){if(on)draft.value.content.expression={instructions:'',explanation_note:''};else delete draft.value.content.expression;}
</script>
<template><HelpHint v-if="draft.kind==='authoring_guideline'" label="全局规范填写说明">全局命题方法无需关联考点。只填写自定义内容与来源，每张最多1500字；不混入医学事实、个人偏好或输出协议。</HelpHint><fieldset :disabled="disabled"><div class="kb-grid"><label>标题<input v-model="draft.title" maxlength="120" required/></label><label>类型<select v-model="draft.kind" aria-label="知识卡类型"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label></div>
<KnowledgePointBinding v-if="draft.kind!=='authoring_guideline'" v-model="draft.knowledge_points" :disabled="disabled"/>
<div v-if="draft.kind!=='authoring_guideline'" class="kb-grid"><label v-for="field in dimensionFields" :key="field.key">{{field.name}}<textarea :aria-label="field.name" v-model="draft.lines[field.key]" rows="4" :placeholder="field.help"/><HelpHint :label="`${field.name}说明`">{{field.help}}</HelpHint></label></div>
<section v-if="draft.kind!=='authoring_guideline'" class="kb-section"><div class="kb-card-top"><h3>事实条目</h3><button type="button" class="ghost-button" :disabled="draft.content.facts.length>=30" @click="addFact()">添加事实</button></div><div v-for="(fact,i) in draft.content.facts" :key="fact.id" class="kb-fact"><label>事实 {{i+1}}<textarea v-model="fact.text" rows="2" maxlength="1000" required/></label><div class="kb-grid"><label>适用前提<input v-model="fact.applies_when" maxlength="600"/></label><label>条目来源<input v-model="fact.source" maxlength="1000"/></label></div><button type="button" class="kb-delete" @click="draft.content.facts.splice(i,1)">移除此事实</button></div></section>
<section v-if="draft.kind==='exam_reference'" class="kb-section"><div class="ui-help-heading"><h3>真题参考</h3><HelpHint label="真题参考说明">仅作为参考资料，不会直接创建题库题目。选用表达要求的新任务只取参考题问法，减少病例和答案照搬；完整原题仍保留在卡片与冻结依据中供查看和首次检查。</HelpHint></div><label>年份或考试名称<input v-model="draft.content.reference.year" maxlength="40"/></label><label>参考题干<textarea v-model="draft.content.reference.stem" rows="4" maxlength="6000"/></label><label v-for="option in draft.content.reference.options" :key="option.label">{{option.label}} 选项<input v-model="option.text" maxlength="600"/></label><label>参考答案<select v-model="draft.content.reference.answer"><option value="">未填写</option><option v-for="label in ['A','B','C','D','E']" :key="label">{{label}}</option></select></label><label>参考解析<textarea v-model="draft.content.reference.explanation" rows="3" maxlength="4000"/></label></section>
<section v-if="draft.kind==='custom'&&(allowExpression||draft.content.expression)" class="kb-section"><label class="expression-choice"><input type="checkbox" aria-label="此卡包含表达要求" :checked="!!draft.content.expression" :disabled="!allowExpression" @change="setExpression($event.target.checked)"/>此卡包含表达要求<HelpHint label="表达要求与参考资料说明">医学资料和真题仍供参考。表达要求需本人启用并勾选，按考点用于知识库工作流；共享须审核通过后由老师选择。解析附言按填写文字在首次检查前加入，不覆盖医学判断、输出协议或权限。</HelpHint></label><template v-if="draft.content.expression"><label>表达要求<textarea v-model="draft.content.expression.instructions" aria-label="表达要求" rows="3" maxlength="4000" placeholder="例如：各选项的理由先说明本例证据，再说明为何不如最佳答案"/></label><label>解析附言（选填）<textarea v-model="draft.content.expression.explanation_note" aria-label="解析附言" rows="2" maxlength="160" placeholder="按填写文字显示在逐项理由之后、故选之前"/></label></template></section>
<label>自定义内容<textarea v-model="draft.content.custom_text" rows="4" maxlength="6000"/></label><label>来源与版本<textarea v-model="draft.source" rows="2" maxlength="2000" placeholder="书名/指南名称、版本年份、章节或页码；真题可记录考试、年份与来源"/></label><label>维护备注<textarea v-model="draft.note" rows="2" maxlength="2000"/></label></fieldset></template>
<style scoped>
.expression-choice{flex-direction:row;align-items:center}.expression-choice input{width:auto}
.kb-selected{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.kb-selected span{display:inline-flex;align-items:center;gap:6px;max-width:100%;min-width:0;overflow-wrap:anywhere;padding:5px 8px;border:1px solid #dbe7f6;border-radius:5px;background:#f1f7ff;font-size:12px;line-height:1.6}.kb-selected button{flex:0 0 20px;width:20px;height:20px;padding:0;border:0;border-radius:4px;background:transparent;color:#6483a5;cursor:pointer}.kb-selected button:hover{background:#e0edfc}.kb-delete{border:0;background:transparent;color:#b45353;font:inherit;cursor:pointer;padding:5px 8px}

fieldset{border:0;margin:0;padding:0;min-width:0}label{display:flex;flex-direction:column;gap:6px;margin:12px 0;font-size:13px;color:#425a73}input,select,textarea{box-sizing:border-box;width:100%;max-width:100%;min-width:0;padding:9px;border:1px solid #d6deea;border-radius:5px;background:white;font:inherit;color:inherit}textarea{resize:vertical;line-height:1.7}.kb-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.kb-section{margin-top:16px;padding-top:12px;border-top:1px solid #e4ebf3}h3{font-size:14px}.kb-filters,.kb-points-edit{display:flex;gap:8px;flex-wrap:wrap}.kb-filters>*{flex:1;min-width:120px}.kb-filters button{flex:0 0 auto}.kb-point-results{display:flex;flex-direction:column;gap:6px;margin-top:10px}.kb-point-results button{text-align:left}.kb-fact{padding:12px;margin:8px 0;background:#f7faff;border:1px solid #e1e9f3;border-radius:6px}.kb-error{color:#b42318}.kb-chip{font-size:12px;border:1px solid #dce6f0;background:#f4f8fd;border-radius:5px;padding:6px}.kb-chip button{border:0;background:transparent;color:#ad3944}@media(max-width:600px){.kb-grid{grid-template-columns:1fr}}
</style>
